import sys

def is_valid_expression(expr, a):
    stack = []
    i = 0
    j = 0
    while i < len(expr):
        if expr[i] == '(':
            stack.append('(')
        elif expr[i] == '0' or expr[i] == '1':
            if j < len(a) and str(a[j]) == expr[i]:
                stack.append(expr[i])
                j += 1
            else:
                return False
        elif expr[i:i+2] == '->':
            if len(stack) >= 2 and stack[-1] in {'0', '1'} and stack[-2] == '(':
                stack.pop()
                stack.pop()
                stack.append('0' if stack[-1] == '1' and expr[i+2] == '0' else '1')
            else:
                return False
            i += 1
        elif expr[i] == ')':
            if len(stack) >= 2 and stack[-1] in ('0', '1'):
                stack.pop()
                if stack and stack[-1] == '(':
                    stack.pop()
                    stack.append(stack[-1])
                else:
                    return False
            else:
                return False
        i += 1
    return len(stack) == 1 and stack[0] == '0'

